import logging
from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import menu
from taf.selenium.sbts.common.exceptions import ParamValueError
from taf.selenium.sbts.pages.menu import wait_for_operation_success


class Menu(menu.Menu):
    """
    The class manages which menu tab will be clicked
    """
    LOGO_XPATH = '//div[@class="ot-product-logo otx-product-logo"]'

    _TARGET_TAB_XPATH = '//ot-menu-item-content//span[text()="{}"]'

    _MENU_XPTAHS_FOR_LEVELS = ['//p-panelmenu//span[text()="{}"]',
                               '//p-panelmenusub//span[text()="{}"]',
                               '//p-panelmenusub//p-panelmenusub//span[text()="{}"]']

    _MENU_CHEVRON_DOWN_XPTAHS_FOR_LEVELS = [
        "//p-panelmenu//span[contains(text(), '{}')]/following-sibling::span[contains(@class, 'mdi-chevron-down')]",
        "//p-panelmenusub//span[contains(text(), '{}')]/parent::*/following-sibling::span[contains(@class, 'mdi-chevron-down')]"
    ]

    _MENU_LIST_EXPAND_XPATH = '//span[@class="p-button-icon mdi mdi-menu"]'
    _MENU_PANEL_XPATH = "//p-panelmenu"

    @wait_for_operation_success
    def open_page(self, menu_list, interval=3, retry=5):  # noqa: C901
        """
        Open a new page of selenium_sbts web, if target page has been opened, it won't be opened again
        :param menu_list: the menu list of selenium_sbts's page
        """
        if not menu_list:
            raise ParamValueError("menu list is empty")

        if self._is_page_active(menu_list):
            return

        self._expand_menu_panel()

        for index, name in enumerate(menu_list):
            menu_xpath = self._MENU_XPTAHS_FOR_LEVELS[index].format(name)
            self._scroll_elem_into_view(self.driver.find_element_by_xpath(menu_xpath))

            logging.info("click menu: {}".format(name))
            if index == len(menu_list) - 1:
                self.click_element_by_xpath(menu_xpath)
                if name == 'BTS Start-up View':
                    return
            else:
                chevron_down_xpath = self._MENU_CHEVRON_DOWN_XPTAHS_FOR_LEVELS[index].format(name)
                if self.element_exists(chevron_down_xpath):
                    self.click_element_by_xpath(menu_xpath)

        self._unexpand_menu_panel()

    def _expand_menu_panel(self):
        if not self.element_exists(self._MENU_PANEL_XPATH):
            self.click_element_by_xpath(self._MENU_LIST_EXPAND_XPATH)

    def _unexpand_menu_panel(self):
        if self.element_exists(self._MENU_PANEL_XPATH):
            self.click_element_by_xpath(self._MENU_LIST_EXPAND_XPATH)
            self.wait_for_invisibility(locator=(By.XPATH, self._MENU_PANEL_XPATH))
